package pflag

import "testing"

func TestLokiProbe(t *testing.T) {
	lokiProbe("p1", "Replace with two values returns nil error and stores them", func() any {
		var target []string
		sv := newStringArrayValue(nil, &target)
		err := sv.Replace([]string{"a", "b"})
		return []any{err, target, sv.GetSlice()}
	})
	lokiProbe("p1", "Replace with empty slice clears the previous value", func() any {
		var target []string
		sv := newStringArrayValue([]string{"old"}, &target)
		err := sv.Replace([]string{})
		return []any{err, target, len(target)}
	})
	lokiProbe("p1", "Replace with nil slice yields an empty non-nil slice", func() any {
		var target []string
		sv := newStringArrayValue([]string{"old"}, &target)
		err := sv.Replace(nil)
		return []any{err, target == nil, len(target)}
	})
	lokiProbe("p1", "Replace copies input: mutating input afterwards does not change stored value", func() any {
		var target []string
		sv := newStringArrayValue(nil, &target)
		in := []string{"x", "y"}
		_ = sv.Replace(in)
		in[0] = "changed"
		return target
	})
	lokiProbe("p1", "Set blank value on first call stores one empty string", func() any {
		var target []string
		sv := newStringArrayValue(nil, &target)
		err := sv.Set("")
		return []any{err, target}
	})
	lokiProbe("p1", "Replace then Set appends to the replaced slice", func() any {
		var target []string
		sv := newStringArrayValue(nil, &target)
		_ = sv.Replace([]string{"r"})
		err := sv.Set("s")
		return []any{err, target}
	})
	lokiProbe("p1", "String of values a and 'b c' via writeAsCSV", func() any {
		var target []string
		sv := newStringArrayValue([]string{"a", "b c"}, &target)
		return sv.String()
	})
	lokiProbe("p1", "stringArrayConv of \"[a,b]\"", func() any {
		v, err := stringArrayConv("[a,b]")
		return []any{v, err}
	})
	lokiProbe("p1", "stringArrayConv of \"[]\" (empty array)", func() any {
		v, err := stringArrayConv("[]")
		return []any{v, err}
	})
	lokiProbe("p1", "stringArrayConv of quoted comma element \"[\\\"a,b\\\",c]\"", func() any {
		v, err := stringArrayConv("[\"a,b\",c]")
		return []any{v, err}
	})
	lokiProbe("p1", "stringArrayConv of padded \" [x] \" (outer whitespace)", func() any {
		v, err := stringArrayConv(" [x] ")
