package cobra

import (
	"io"
	"os"
	"testing"
)

func TestLokiProbe(t *testing.T) {
	capture := func(stream **os.File, f func()) string {
		r, w, err := os.Pipe()
		if err != nil {
			return err.Error()
		}
		old := *stream
		*stream = w
		f()
		*stream = old
		w.Close()
		b, _ := io.ReadAll(r)
		r.Close()
		return string(b)
	}
	newRoot := func(comps []Completion, dir ShellCompDirective) *Command {
		return &Command{
			Use: "root",
			Run: emptyRun,
			ValidArgsFunction: func(cmd *Command, args []string, toComplete string) ([]Completion, ShellCompDirective) {
				return comps, dir
			},
		}
	}
	findComplete := func() *Command {
		c := &Command{Use: "root", Run: emptyRun}
		c.initCompleteCmd([]string{"__complete", "x"})
		sub, _, _ := c.Find([]string{"__complete"})
		return sub
	}

	lokiProbe("p1", "[s1] CompErrorln(\"disk full\") writes the message to stderr", func() any {
		return capture(&os.Stderr, func() { CompErrorln("disk full") })
	})
	lokiProbe("p1", "[s2] nil Command execute returns the nil-command error", func() any {
		var c *Command
		err := c.execute([]string{})
		return err
	})
	lokiProbe("p1", "[s3] initCompleteCmd builds __complete with its Use line", func() any {
		return findComplete().Use
	})
	lokiProbe("p1", "[s4] deprecated child prints the deprecation notice", func() any {
		root := &Command{Use: "root", Run: emptyRun}
		child := &Command{Use: "child", Run: emptyRun, Deprecated: "use other"}
		root.AddCommand(child)
		out, err := executeCommand(root, "child")
		return []any{out, err}
	})
	lokiProbe("p1", "[s5] initCompleteCmd Long text for __complete", func() any {
		return findComplete().Long
	})
	lokiProbe("p1", "[s6] help flag declared as string instead of bool", func() any {
		root := &Command{Use: "root", Run: emptyRun}
		root.Flags().String("help", "", "help text")
		out, err := executeCommand(root)
		return []any{out, err}
	})
	lokiProbe("p1", "[s7] NoDesc completion strips description: apple<TAB>fruit", func() any {
		root := newRoot([]Completion{CompletionWithDesc("apple", "fruit")}, ShellCompDirectiveNoFileComp)
		out, err := executeCommand(root, ShellCompNoDescRequestCmd, "x")
		return []any{out, err}
	})
	lokiProbe("p1", "[s8] root command with Version 1.2.3 prints version on --version", func() any {
		root := &Command{Use: "root", Version: "1.2.3", Run: emptyRun}
		out, err := executeCommand(root, "--version")
		return []any{out, err}
	})
	lokiProbe("p1", "[s9] completion with a line break: line1 newline line2 keeps only line1", func() any {
		root := newRoot([]Completion{"line1\nline2"}, ShellCompDirectiveDefault)
		out, err := executeCommand(root, ShellCompRequestCmd, "x")
		return []any{out, err}
	})
	lokiProbe("p1", "[s10] version flag declared as string instead of bool", func() any {
		root := &Command{Use: "root", Version: "1.2.3", Run: emptyRun}
		root.Flags().String("version", "", "version text")
		out, err := executeCommand(root)
		return []any{out, err}
	})
	lokiProbe("p1", "[s11] padded completion \"  padded  \" is trimmed", func() any {
		root := newRoot([]Completion{"  padded  "}, ShellCompDirectiveDefault)
		out, err := executeCommand(root, ShellCompRequestCmd, "x")
		return []any{out, err}
	})
	lokiProbe("p1", "[s12] plain completion tomato is printed with a newline", func() any {
		root := newRoot([]Completion{"tomato"}, ShellCompDirectiveDefault)
		out, err := executeCommand(root, ShellCompRequestCmd, "x")
		return []any{out, err}
	})
	lokiProbe("p1", "[s13] directive line for NoFileComp (:4) with no completions", func() any {
		root := newRoot(nil, ShellCompDirectiveNoFileComp)
		out, err := executeCommand(root, ShellCompRequestCmd, "x")
		return []any{out, err}
	})
	lokiProbe("p1", "[s14] stderr line for NoSpace|NoFileComp directive", func() any {
		root := newRoot([]Completion{"a"}, ShellCompDirectiveNoSpace|ShellCompDirectiveNoFileComp)
		out, err := executeCommand(root, ShellCompRequestCmd, "x")
		return []any{out, err}
	})
	lokiProbe("p1", "issue example: __complete x with TraverseChildren leaves os.Args unchanged", func() any {
		before := append([]string(nil), os.Args...)
		root := &Command{
			Use:              "root",
			Run:              emptyRun,
			TraverseChildren: true,
			ValidArgsFunction: func(cmd *Command, args []string, toComplete string) ([]Completion, ShellCompDirective) {
				return nil, ShellCompDirectiveDefault
			},
		}
		out, err := executeCommand(root, ShellCompRequestCmd, "x")
		after := append([]string(nil), os.Args...)
		os.Args = before
		return []any{out, err, before, after}
	})
}

