		c, err := NewConstraint(con)
		if err != nil {
			return err
		}
		v, err := NewVersion(ver)
		if err != nil {
			return err
		}
		return c.Check(v)
	}

	lokiProbe("p1", "[*] bare * constraint against 1.2.3 (issue: expect true)", func() any {
		return check("*", "1.2.3")
	})
