	lokiProbe("p1", "* with surrounding spaces against 10.20.30", func() any {
		return check(" * ", "10.20.30")
	})
	lokiProbe("p1", "x constraint against 3.0.1", func() any {
		return check("x", "3.0.1")
	})
	lokiProbe("p1", "*.* constraint against 2.5.0", func() any {
		return check("*.*", "2.5.0")
	})
	lokiProbe("p1", "* constraint against prerelease 1.2.3-rc.1", func() any {
		return check("*", "1.2.3-rc.1")
	})
	lokiProbe("p1", ">=* constraint against 5.0.0", func() any {
		return check(">=*", "5.0.0")
	})
	lokiProbe("p1", "~* constraint against 9.9.9", func() any {
		return check("~*", "9.9.9")
	})
	lokiProbe("p1", "^* constraint against 9.9.9", func() any {
		return check("^*", "9.9.9")
	})
	lokiProbe("p1", "1.* constraint against 2.0.0 (boundary, expect false)", func() any {
		return check("1.*", "2.0.0")
	})
	lokiProbe("p1", "OR list \"1.0.0 || *\" against 7.0.0", func() any {
		return check("1.0.0 || *", "7.0.0")
	})
	lokiProbe("p1", "parseConstraint(\"*\") dirty flags and major, isX variants", func() any {
		cs, err := parseConstraint("*")
		if err != nil {
			return err
		}
		return []any{cs.dirty, cs.minorDirty, cs.con.Major(), isX("*"), isX("X"), isX("x1")}
	})
}

